        domain = parsed.netloc.split(':')[0].lower()
        if domain.startswith('www.'):
            domain = domain[4:]
        if domain:
            domains.add(domain)
    result = {}
    for domain in domains:
        try:
            api_url = f'http://ip-api.com/json/{domain}?key={API_KEY}'
