HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, timeout=10)
    except Exception as e:
        raise Exception(f"Error accessing URL: {e}")
    if response.status_code != 200:
        raise Exception(f"Failed to retrieve data, status code: {response.status_code}")
    try:
        data = response.json()
    except ValueError:
        raise Exception("Invalid JSON response")
    if data is None:
        raise Exception("Empty data")
    if isinstance(data, dict):
        if "data" in data:
            data = data["data"]
        else:
            data = [data]
    if not isinstance(data, list) or len(data) == 0:
        raise Exception("Invalid or empty data structure")
    try:
        df = pd.DataFrame(data)
    except Exception:
        raise Exception("Cannot convert data to DataFrame")
    if df.empty:
        raise Exception("Empty DataFrame")
    numeric_df = df.select_dtypes(include="number")
    if numeric_df.empty:
        raise Exception("No numerical data available for correlation")
    corr = numeric_df.corr()
    ax = sns.heatmap(corr, annot=True, cmap="viridis")
    return df, ax

