# Constants
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    recipients = []
    if isinstance(data, dict):
        if "recipients" in data:
            recipients = data["recipients"]
        else:
            recipients = [data]
    elif isinstance(data, list):
        recipients = data
    names = []
    emails = []
    for item in recipients:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        email = item.get("email")
        if isinstance(name, str) and isinstance(email, str):
            names.append(name)
            emails.append(email)
    if not names or not emails:
        return []
    message_lines = ["Subject: Extracted Names", ""]
    message_lines.extend(names)
    message = "\n".join(message_lines)
    close_smtp = False
    server = smtp
    try:
        if server is None:
            server = smtplib.SMTP(smtp_server, smtp_port)
            close_smtp = True
            server.starttls()
            server.login(email_address, email_password)
        server.sendmail(email_address, emails, message)
    finally:
        if close_smtp and server is not None:
            try:
                server.quit()
            except Exception:
                pass
    return names

