import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.isfile(file_path):
        raise ValueError("File does not exist")

    with open(file_path, "r") as f:
        data = json.load(f)

    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    properties = INPUT_JSON.get("properties", {})
    for field, spec in properties.items():
        if field in data:
            expected_type = spec.get("type")
            if expected_type is not None and not isinstance(data[field], expected_type):
                raise ValueError(f"Field '{field}' has incorrect type")

    email_value = data.get("email")
    if not isinstance(email_value, str) or re.fullmatch(EMAIL_REGEX, email_value) is None:
        raise ValueError("Invalid email format")

    if attribute not in data or attribute not in properties:
        raise ValueError("Requested attribute is not defined in schema or not present in data")

    expected_type = properties[attribute].get("type")
    value = data[attribute]
    if expected_type is not None and not isinstance(value, expected_type):
        raise ValueError("Requested attribute does not match expected type")

    return value

