from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    continue
                if isinstance(data, dict):
                    texts = [v for v in data.values() if isinstance(v, str)]
                elif isinstance(data, list):
                    texts = []
                    for item in data:
                        if isinstance(item, dict):
                            texts.extend([v for v in item.values() if isinstance(v, str)])
                        elif isinstance(item, str):
                            texts.append(item)
                else:
                    texts = []
                for text in texts:
                    text = text.lower()
                    cleaned = []
                    for ch in text:
                        if ch.isalnum() or ch.isspace():
                            cleaned.append(ch)
                    cleaned_text = ''.join(cleaned)
                    words = cleaned_text.split()
                    all_words.extend(words)
    counter = Counter(all_words)
    return counter.most_common(word_count)

