from glob import glob
def task_func(directory, string):
    def contains_string(obj, target):
        if isinstance(obj, dict):
            for v in obj.values():
                if contains_string(v, target):
                    return True
            return False
        if isinstance(obj, list):
            for item in obj:
                if contains_string(item, target):
                    return True
            return False
        if isinstance(obj, str):
            return obj == target
        return False
    pattern = directory.rstrip('/') + '/**/*.json'
    json_files = glob(pattern, recursive=True)
    result = []
    for path in json_files:
        try:
            with open(path, 'r') as f:
                data = json.load(f)
        except Exception:
            continue
        if contains_string(data, string):
            result.append(path)
    return result

