import shutil
def task_func(path):
    if not os.path.isdir(path):
        return pd.DataFrame()
    files = sorted(f for f in os.listdir(path) if f.endswith('.json') and os.path.isfile(os.path.join(path, f)))
    dataframes = []
    processed_dir = os.path.join(path, 'processed')
    if files and not os.path.exists(processed_dir):
        os.makedirs(processed_dir)
    for filename in files:
        file_path = os.path.join(path, filename)
        with open(file_path, 'r') as f:
            try:
                content = json.load(f)
            except json.JSONDecodeError:
                continue
        if isinstance(content, list):
            df = pd.DataFrame(content)
        elif isinstance(content, dict):
            df = pd.DataFrame([content])
        else:
            df = pd.DataFrame([{'value': content}])
        df['Source'] = filename
        dataframes.append(df)
        shutil.move(file_path, os.path.join(processed_dir, filename))
    if not dataframes:
        return pd.DataFrame()
    return pd.concat(dataframes, ignore_index=True)

