import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception:
        raise ValueError("Malformed JSON data")
    if not data:
        raise ValueError("Empty JSON data")
    if isinstance(data, dict):
        data_list = [data]
    elif isinstance(data, list):
        data_list = data
    else:
        raise ValueError("JSON data must be a list or dict")
    countries = []
    populations = []
    for item in data_list:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing Country or Population field")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = math.floor(population)
        countries.append(country)
        populations.append(population_int)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    if not os.path.isdir(output_dir):
        raise IOError("Output directory does not exist")
    output_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(output_path, index=False)
    except Exception:
        raise IOError("Failed to write CSV file")
    return output_path, df

