import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    def to_float_or_none(x):
        try:
            return float(x)
        except (ValueError, TypeError):
            return None
    normalized = {}
    num_pattern = re.compile(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?')
    for k, v in data.items():
        if isinstance(v, (int, float)):
            normalized[k] = float(v) * 2.0
        elif isinstance(v, list):
            new_list = []
            all_numeric = True
            for item in v:
                fv = to_float_or_none(item)
                if fv is None:
                    all_numeric = False
                    break
                new_list.append(fv * 2.0)
            if all_numeric:
                normalized[k] = new_list
            else:
                normalized[k] = v
        elif isinstance(v, str):
            match = num_pattern.search(v)
            if match:
                num = float(match.group(0))
                normalized[k] = num * 2.0
            else:
                normalized[k] = v
        else:
            normalized[k] = v
    try:
        df = pd.DataFrame.from_dict(normalized)
    except Exception:
        return pd.DataFrame()
    if df.empty:
        return pd.DataFrame()
    return df

